"use client";

import { cn } from "@repo/smoothui-utils";
import { ChevronDown } from "lucide-react";
import { motion, useReducedMotion } from "motion/react";
import { Accordion as AccordionPrimitive } from "radix-ui";
import type { ComponentProps, ReactNode } from "react";
import { DURATION, DURATION_INSTANT, EASE_OUT } from "../../lib/animation";

type AccordionRootBase = Omit<
  ComponentProps<typeof AccordionPrimitive.Root>,
  "type" | "value" | "defaultValue" | "onValueChange"
> & {
  className?: string;
};

/**
 * Single mode is the default (`type` omitted, `multiple` false). Value is a
 * string — the Base twin takes `string[]`, and passing an array through to
 * Radix single mode is the faq-2 class (#160). Multiple mode takes `string[]`.
 */
export type AccordionRootProps =
  | (AccordionRootBase & {
      multiple?: false;
      type?: "single";
      value?: string;
      defaultValue?: string;
      onValueChange?: (value: string) => void;
    })
  | (AccordionRootBase & {
      multiple: true;
      type?: "multiple";
      value?: string[];
      defaultValue?: string[];
      onValueChange?: (value: string[]) => void;
    })
  | (AccordionRootBase & {
      multiple?: boolean;
      type: "multiple";
      value?: string[];
      defaultValue?: string[];
      onValueChange?: (value: string[]) => void;
    });

export type AccordionItemProps = ComponentProps<
  typeof AccordionPrimitive.Item
> & {
  className?: string;
};

export type AccordionHeaderProps = ComponentProps<
  typeof AccordionPrimitive.Header
> & {
  className?: string;
};

export type AccordionTriggerProps = ComponentProps<
  typeof AccordionPrimitive.Trigger
> & {
  className?: string;
  children?: ReactNode;
  hideChevron?: boolean;
};

export type AccordionPanelProps = ComponentProps<
  typeof AccordionPrimitive.Content
> & {
  className?: string;
  children?: ReactNode;
};

export type AccordionProps = AccordionRootProps;

const PANEL_EASE = "ease-[cubic-bezier(0.23,1,0.32,1)]";

const firstOf = (value?: string | string[]): string | undefined =>
  Array.isArray(value) ? value[0] : value;

const asArray = (value?: string | string[]): string[] | undefined => {
  if (value === undefined) {
    return;
  }
  return Array.isArray(value) ? value : [value];
};

const accordionRootClassName = (className?: string) =>
  cn(
    "flex w-full min-w-0 flex-col divide-y divide-foreground/15 overflow-hidden rounded-lg border border-foreground/20",
    className
  );

/**
 * SmoothUI Accordion — Radix twin.
 * Panel uses `--radix-accordion-content-height`.
 * Single-mode value is a string at the type level; firstOf still unwraps a
 * Base-style array at runtime so already-shipped blocks (faq-2) keep working.
 */
const AccordionRoot = ({
  className,
  multiple = false,
  type,
  value,
  defaultValue,
  onValueChange,
  ...props
}: AccordionRootProps) => {
  const resolvedType = type ?? (multiple ? "multiple" : "single");

  if (resolvedType === "multiple") {
    const handleMultiple = onValueChange as
      | ((next: string[]) => void)
      | undefined;
    return (
      <AccordionPrimitive.Root
        className={accordionRootClassName(className)}
        data-slot="accordion"
        defaultValue={asArray(defaultValue)}
        onValueChange={(next) => {
          handleMultiple?.(next);
        }}
        type="multiple"
        value={asArray(value)}
        {...props}
      />
    );
  }

  const handleSingle = onValueChange as ((next: string) => void) | undefined;
  return (
    <AccordionPrimitive.Root
      className={accordionRootClassName(className)}
      data-slot="accordion"
      defaultValue={firstOf(defaultValue)}
      onValueChange={(next) => {
        handleSingle?.(next);
      }}
      type="single"
      value={firstOf(value)}
      {...props}
    />
  );
};

const AccordionItem = ({ className, ...props }: AccordionItemProps) => (
  <AccordionPrimitive.Item
    className={cn("group min-w-0 overflow-hidden", className)}
    data-slot="accordion-item"
    {...props}
  />
);

const AccordionHeader = ({ className, ...props }: AccordionHeaderProps) => (
  <AccordionPrimitive.Header
    className={cn("m-0 flex w-full min-w-0", className)}
    data-slot="accordion-header"
    {...props}
  />
);

const AccordionTrigger = ({
  className,
  children,
  hideChevron = false,
  ...props
}: AccordionTriggerProps) => {
  const shouldReduceMotion = useReducedMotion();
  return (
    <AccordionPrimitive.Trigger
      className={cn(
        "group flex w-full min-w-0 select-none items-center justify-between gap-3 bg-transparent px-4 py-3.5 text-left font-medium text-sm outline-none",
        "hover:bg-foreground/5 focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-inset",
        "disabled:pointer-events-none disabled:text-muted-foreground",
        className
      )}
      data-slot="accordion-trigger"
      {...props}
    >
      <span className="min-w-0 flex-1">{children}</span>
      {hideChevron ? null : (
        <ChevronDown
          aria-hidden
          className={cn(
            "size-4 shrink-0 text-muted-foreground",
            shouldReduceMotion
              ? "transition-none"
              : `transition-transform duration-200 ${PANEL_EASE}`,
            "group-data-[state=open]:rotate-180 [[data-state=open]_&]:rotate-180"
          )}
        />
      )}
    </AccordionPrimitive.Trigger>
  );
};

type AccordionSurfaceProps = ComponentProps<typeof motion.div> & {
  "data-state"?: string;
};

/**
 * Height surface. Radix hands `data-state` to the child through `asChild`, so
 * the open state needs no extra context. The surface animates height between
 * 0 and "auto" with Motion; the closed panel is also `inert` and `aria-hidden`
 * and turns `visibility: hidden` once the close finishes, so it leaves the
 * a11y tree and the tab order.
 */
const AccordionSurface = ({
  "data-state": state,
  ...props
}: AccordionSurfaceProps) => {
  const shouldReduceMotion = useReducedMotion();
  const isOpen = state === "open";
  return (
    <motion.div
      {...props}
      animate={{
        height: isOpen ? "auto" : 0,
        opacity: isOpen ? 1 : 0,
        visibility: isOpen ? "visible" : "hidden",
      }}
      aria-hidden={isOpen ? undefined : true}
      data-state={state}
      inert={!isOpen}
      initial={false}
      transition={
        shouldReduceMotion
          ? DURATION_INSTANT
          : { duration: DURATION.default, ease: EASE_OUT }
      }
    />
  );
};

const AccordionPanel = ({
  className,
  children,
  ...props
}: AccordionPanelProps) => (
  <AccordionPrimitive.Content
    asChild
    data-slot="accordion-panel"
    forceMount
    {...props}
  >
    <AccordionSurface
      className={cn("overflow-hidden text-muted-foreground text-sm", className)}
    >
      <div className="px-4 pt-0 pb-4 leading-relaxed">{children}</div>
    </AccordionSurface>
  </AccordionPrimitive.Content>
);

export {
  AccordionHeader,
  AccordionItem,
  AccordionPanel,
  AccordionRoot,
  AccordionTrigger,
};

export default AccordionRoot;

