import { describe, expect, it } from "vitest";
import {
  AI_ACCENT_COLORS,
  AI_STATE_MOTION,
  type AIState,
  getAIStateAccentColor,
  getAIStateMotion,
} from "../index";

const ALL_STATES: AIState[] = [
  "idle",
  "listening",
  "thinking",
  "streaming",
  "done",
  "error",
];

describe("AI_STATE_MOTION", () => {
  it("covers every state", () => {
    for (const state of ALL_STATES) {
      expect(AI_STATE_MOTION[state]).toBeDefined();
    }
  });

  it("gives every state a distinct motif", () => {
    const motifs = ALL_STATES.map((state) => AI_STATE_MOTION[state].motif);
    expect(new Set(motifs).size).toBe(ALL_STATES.length);
  });

  it("keeps thinking at rest scale so the layout stays calm while working", () => {
    expect(AI_STATE_MOTION.thinking.scale).toBe(1);
  });

  it("churns hardest while thinking, without growing", () => {
    const { thinking } = AI_STATE_MOTION;
    for (const state of ALL_STATES) {
      expect(thinking.turbulence).toBeGreaterThanOrEqual(
        AI_STATE_MOTION[state].turbulence
      );
    }
  });

  it("settles the field almost still on done", () => {
    expect(AI_STATE_MOTION.done.turbulence).toBeLessThan(
      AI_STATE_MOTION.idle.turbulence + 0.1
    );
  });

  it("stalls the tumble on error so the surface twitches instead of flowing", () => {
    expect(AI_STATE_MOTION.error.tumble).toBe(0);
    expect(AI_STATE_MOTION.error.turbulence).toBeGreaterThan(0);
  });

  it("desaturates error instead of enlarging it", () => {
    expect(AI_STATE_MOTION.error.saturation).toBeLessThan(1);
    expect(AI_STATE_MOTION.error.scale).toBeLessThanOrEqual(1);
  });

  it("only reacts to amplitude when the state implies listening", () => {
    expect(AI_STATE_MOTION.listening.reactivity).toBeGreaterThan(
      AI_STATE_MOTION.thinking.reactivity
    );
    expect(AI_STATE_MOTION.idle.reactivity).toBe(0);
    expect(AI_STATE_MOTION.error.reactivity).toBe(0);
  });
});

describe("getAIStateMotion", () => {
  it("falls back to idle for an undefined state", () => {
    expect(getAIStateMotion(undefined)).toBe(AI_STATE_MOTION.idle);
  });

  it("returns the matching preset", () => {
    expect(getAIStateMotion("done")).toBe(AI_STATE_MOTION.done);
  });
});

describe("getAIStateAccentColor", () => {
  it("uses the semantic accent for done and error", () => {
    expect(getAIStateAccentColor("done", "#fff")).toBe(
      AI_ACCENT_COLORS.success
    );
    expect(getAIStateAccentColor("error", "#fff")).toBe(
      AI_ACCENT_COLORS.danger
    );
  });

  it("falls back to the caller's own colour otherwise", () => {
    for (const state of [
      "idle",
      "listening",
      "thinking",
      "streaming",
    ] as const) {
      expect(getAIStateAccentColor(state, "#abcdef")).toBe("#abcdef");
    }
  });
});

"use client";

import {
  type MotionValue,
  useAnimationFrame,
  useMotionValue,
} from "motion/react";
import { useCallback, useEffect, useRef, useState } from "react";

/**
 * The single state contract shared by every SmoothUI AI component.
 *
 * Passing the same value to an orb, a prompt input and a tool card makes the
 * whole surface move as one organism instead of a set of independent widgets.
 */
export type AIState =
  | "idle"
  | "listening"
  | "thinking"
  | "streaming"
  | "done"
  | "error";

/**
 * A behavioural hint each component expresses **in its own material**.
 *
 * Deliberately not an overlay. Bolting one shared graphic onto every orb makes
 * four different materials look like the same widget wearing a costume, and it
 * pushes literal iconography (a checkmark, a warning ring) onto pieces that are
 * decorative by nature. Instead: a shader warps, a canvas ring loses harmonics,
 * a character changes expression. Same vocabulary, different flesh.
 */
export type AIStateMotif =
  | "breathe"
  | "receive"
  | "scan"
  | "pulse"
  | "ping"
  | "fault";

/** Semantic accent applied on top of the component's own palette. */
export type AIStateAccent = "success" | "danger" | null;

/** Motion parameters a component reads to render a given {@link AIState}. */
export type AIStateMotion = {
  /** Semantic colour override, so status is carried by hue and not only motion. */
  accent: AIStateAccent;
  /** Outer bloom strength, 0–1. */
  glow: number;
  /** Palette hue rotation in degrees. Small shifts read as a mood change. */
  hueRotate: number;
  /** Overall motion energy, 0–1. Scales ambient loops and displacement. */
  intensity: number;
  /** Behavioural hint; each component expresses it in its own material. */
  motif: AIStateMotif;
  /** Seconds between discrete pulses, for rhythmic behaviour. */
  pulseSeconds: number;
  /**
   * How far a shader's domain warp pushes the field, 0–1. Low values read as a
   * calm surface; high values churn without the silhouette growing.
   */
  turbulence: number;
  /** Revolutions per second of the noise field — the slow tumble. */
  tumble: number;
  /** How much external amplitude reaches the surface, 0 = ignore it. */
  reactivity: number;
  /** Chroma multiplier. Below 1 desaturates. */
  saturation: number;
  /** Resting scale of the surface, 1 = no change. */
  scale: number;
  /** Ambient loop speed multiplier, 1 = the component's base tempo. */
  speed: number;
};

/**
 * Per-state presets.
 *
 * Deliberate choices worth keeping:
 * - `thinking` has `scale: 1` — internal churn only, so layout stays calm while
 *   the model works. Growing the surface here makes pages feel unstable.
 * - `error` desaturates instead of growing, so it reads as a state change
 *   rather than an attention grab.
 * - `done` overshoots once; components are expected to settle back to `idle`.
 * - Each state owns a distinct `motif`, so the six states are told apart by
 *   what moves, not by how fast it moves.
 */
